{
  "findings": [
    {
      "check_id": "CKV_AWS_317",
      "title": "Elasticsearch audit logging is disabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The domain has no AUDIT_LOGS publishing configuration, preventing security-relevant access and authorization events from being centrally recorded."
    },
    {
      "check_id": "CKV_AWS_318",
      "title": "Elasticsearch lacks three dedicated master nodes",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The cluster does not enable dedicated master nodes, increasing the risk of loss of cluster coordination and availability during node failures."
    },
    {
      "check_id": "CKV_AWS_84",
      "title": "Elasticsearch operational logging is disabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "No application log publishing is configured, limiting detection and investigation of service errors and abnormal domain activity."
    },
    {
      "check_id": "CKV_AWS_5",
      "title": "Elasticsearch encryption at rest is disabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The encrypt_at_rest block explicitly disables encryption, leaving domain data unprotected at the storage encryption layer."
    },
    {
      "check_id": "CKV_AWS_247",
      "title": "Elasticsearch does not use a customer-managed KMS key",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The domain has no customer-managed KMS key configured, preventing direct control over key rotation, lifecycle, and authorization."
    },
    {
      "check_id": "CKV_AWS_6",
      "title": "Elasticsearch node-to-node encryption is disabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The domain does not enable node-to-node encryption, so traffic exchanged between cluster nodes is not explicitly protected in transit."
    },
    {
      "check_id": "CKV_AWS_228",
      "title": "Elasticsearch does not enforce a current TLS policy",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The domain does not enforce HTTPS or declare a minimum TLS 1.2 policy, allowing weaker endpoint transport settings."
    },
    {
      "check_id": "CKV2_AWS_59",
      "title": "Elasticsearch dedicated master nodes are disabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The cluster configuration only defines data instances and does not enable dedicated master nodes for stable cluster management."
    },
    {
      "check_id": "CKV2_AWS_52",
      "title": "Elasticsearch fine-grained access control is disabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The domain lacks advanced security options, so fine-grained index, document, and field-level authorization is not enabled."
    }
  ],
  "patched_code": "data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

resource "aws_kms_key" "elasticsearch" {
  description         = "KMS key for the enterprise log analytics Elasticsearch domain"
  enable_key_rotation = true
}

resource "aws_cloudwatch_log_group" "elasticsearch_application" {
  name              = "/aws/elasticsearch/enterprise-log-analytics-es/application"
  retention_in_days = 365
}

resource "aws_cloudwatch_log_group" "elasticsearch_audit" {
  name              = "/aws/elasticsearch/enterprise-log-analytics-es/audit"
  retention_in_days = 365
}

resource "aws_cloudwatch_log_resource_policy" "elasticsearch_logs" {
  policy_name = "enterprise-log-analytics-es-logs"

  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "es.amazonaws.com"
        }
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          "${aws_cloudwatch_log_group.elasticsearch_application.arn}:*",
          "${aws_cloudwatch_log_group.elasticsearch_audit.arn}:*"
        ]
        Condition = {
          ArnLike = {
            "aws:SourceArn" = "arn:${data.aws_partition.current.partition}:es:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:domain/enterprise-log-analytics-es"
          }
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_elasticsearch_domain" "log_search_database" {
  domain_name           = "enterprise-log-analytics-es"
  elasticsearch_version = "7.10"

  cluster_config {
    instance_type          = var.elasticsearch_instance_type
    instance_count         = 2
    dedicated_master_enabled = true
    dedicated_master_count   = 3
    dedicated_master_type    = "m5.large.elasticsearch"
  }

  vpc_options {
    subnet_ids         = [aws_subnet.data_subnet_az1.id]
    security_group_ids = [aws_security_group.elasticsearch_sg.id]
  }

  ebs_options {
    ebs_enabled = true
    volume_size = 20
    volume_type = "gp2"
  }

  encrypt_at_rest {
    enabled    = true
    kms_key_id = aws_kms_key.elasticsearch.arn
  }

  node_to_node_encryption {
    enabled = true
  }

  domain_endpoint_options {
    enforce_https       = true
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }

  advanced_security_options {
    enabled                        = true
    internal_user_database_enabled = false

    master_user_options {
      master_user_arn = data.aws_caller_identity.current.arn
    }
  }

  log_publishing_options {
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.elasticsearch_application.arn
    log_type                 = "ES_APPLICATION_LOGS"
    enabled                  = true
  }

  log_publishing_options {
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.elasticsearch_audit.arn
    log_type                 = "AUDIT_LOGS"
    enabled                  = true
  }

  depends_on = [aws_cloudwatch_log_resource_policy
